 function seekPointer(e){
  if(e.button!==0||S.recording||e.target.closest('.pv-shot'))return;e.preventDefault();h.setPlaying(false);dragCleanup?.();
  const ruler=footer.querySelector('.pv-ruler'),pointer=e.pointerId;ruler.setPointerCapture?.(pointer);
  const seek=ev=>{if(ev.pointerId!==pointer)return;h.setPlayhead(frameAt(ev.clientX,ruler.getBoundingClientRect(),S.project.sequence.durationFrames));update();};
  const end=ev=>{if(ev&&ev.pointerId!==pointer)return;dragCleanup?.();};
  const move=ev=>{ev.preventDefault();seek(ev);};
  dragCleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);if(ruler.hasPointerCapture?.(pointer))ruler.releasePointerCapture(pointer);dragCleanup=null;};
  window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);seek(e);
 }
